function ConvertTo-WsmServiceSupplementNativeInput($Supplement) {
    $errorControlCode=@{Ignore=0;Normal=1;Severe=2;Critical=3}[$Supplement.ErrorControl];$sid=@{None=0;Unrestricted=1;Restricted=3}[$Supplement.ServiceSidType];$action=@{None=0;Restart=1;Reboot=2;RunCommand=3};$types=[int[]]@($Supplement.FailureActions.Actions | ForEach-Object {$action[$_.Type]});$delays=[uint32[]]@($Supplement.FailureActions.Actions | ForEach-Object {[uint32]$_.DelayMilliseconds});$reset=[uint32]::MaxValue;if($Supplement.FailureActions.ResetPeriodSeconds -cne 'Infinite'){$reset=[uint32]$Supplement.FailureActions.ResetPeriodSeconds}
    $triggerList=New-Object 'System.Collections.Generic.List[object[]]';foreach($trigger in $Supplement.Triggers){$dataList=New-Object 'System.Collections.Generic.List[object[]]';foreach($data in $trigger.DataItems){$dataList.Add([object[]]@([uint32]$data.Type,[string]$data.DataBase64))};$triggerAction=1;if($trigger.Action -ceq 'Stop'){$triggerAction=2};$triggerList.Add([object[]]@([uint32]$trigger.Type,[uint32]$triggerAction,[string]$trigger.Subtype,$dataList.ToArray()))}
    [pscustomobject]@{ErrorControl=[uint32]$errorControlCode;LoadOrderGroup=[string]$Supplement.LoadOrderGroup;DelayedAutoStart=[bool]$Supplement.DelayedAutoStart;ServiceSidType=[uint32]$sid;RequiredPrivileges=[string[]]@($Supplement.RequiredPrivileges);Environment=[string[]]@($Supplement.Environment);ResetPeriodSeconds=$reset;RebootMessage=[string]$Supplement.FailureActions.RebootMessage;Command=[string]$Supplement.FailureActions.Command;ActionTypes=$types;ActionDelays=$delays;FailureActionsOnNonCrashFailures=[bool]$Supplement.FailureActionsOnNonCrashFailures;Triggers=$triggerList.ToArray()}
}
function Get-WsmServiceSupplementNativeState([string]$Name) {Initialize-WsmServiceSupplementNative;return ,([WsmServiceSupplementNative]::Read($Name))}
function Invoke-WsmServiceSupplementNative([string]$Name,$NativeConfig) {Initialize-WsmServiceSupplementNative;[WsmServiceSupplementNative]::Apply($Name,$NativeConfig.ErrorControl,$NativeConfig.LoadOrderGroup,$NativeConfig.DelayedAutoStart,$NativeConfig.ServiceSidType,$NativeConfig.RequiredPrivileges,$NativeConfig.ResetPeriodSeconds,$NativeConfig.RebootMessage,$NativeConfig.Command,$NativeConfig.ActionTypes,$NativeConfig.ActionDelays,$NativeConfig.FailureActionsOnNonCrashFailures,$NativeConfig.Triggers)}
function Get-WsmServiceEnvironment([string]$Name) {Assert-WsmServiceSupplementName $Name;$registry=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey(('SYSTEM\CurrentControlSet\Services\'+$Name),$false);if(-not $registry){throw 'Service registry key is unavailable.'};try{if($registry.GetValueNames() -contains 'Environment'){@($registry.GetValue('Environment',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames))}else{@()}}finally{$registry.Dispose()}}
function Set-WsmServiceEnvironment([string]$Name,[string[]]$Values) {Assert-WsmServiceSupplementName $Name;$registry=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey(('SYSTEM\CurrentControlSet\Services\'+$Name),$true);if(-not $registry){throw 'Service registry key is unavailable.'};try{if($Values.Count){$registry.SetValue('Environment',[string[]]$Values,[Microsoft.Win32.RegistryValueKind]::MultiString)}elseif($registry.GetValueNames() -contains 'Environment'){$registry.DeleteValue('Environment',$false)}}finally{$registry.Dispose()}}
function ConvertFrom-WsmServiceSupplementState($Actual,[string[]]$Environment=@()) {
    if($Actual -is [array]){if($Actual.Count -lt 9){throw 'Native service supplement state is incomplete.'};$raw=$Actual;$Actual=[pscustomobject]@{ServiceType=$raw[0];ErrorControl=$raw[1];LoadOrderGroup=$raw[2];DelayedAutoStart=$raw[3];FailureActions=$raw[4];FailureActionsOnNonCrashFailures=$raw[5];ServiceSidType=$raw[6];RequiredPrivileges=$raw[7];Environment=$Environment;Triggers=$raw[8]}}
    $serviceTypes=@{'16'='Win32OwnProcess'};$errors=@{'0'='Ignore';'1'='Normal';'2'='Severe';'3'='Critical'};$sidTypes=@{'0'='None';'1'='Unrestricted';'3'='Restricted'};$actionTypes=@{'0'='None';'1'='Restart';'2'='Reboot';'3'='RunCommand'}
    $type=$serviceTypes[[string]([uint32]$Actual.ServiceType)];if(-not $type){$type='UnsupportedServiceType:'+([uint32]$Actual.ServiceType)};$error=$errors[[string]([uint32]$Actual.ErrorControl)];if(-not $error){$error='UnsupportedErrorControl:'+([uint32]$Actual.ErrorControl)};$sid=$sidTypes[[string]([uint32]$Actual.ServiceSidType)];if(-not $sid){$sid='UnsupportedServiceSidType:'+([uint32]$Actual.ServiceSidType)}
    $f=$Actual.FailureActions;$reset=[uint32]$f[0];if($reset -eq [uint32]::MaxValue){$reset='Infinite'};$actions=@(foreach($a in $f[3]){$name=$actionTypes[[string]([int]$a[0])];if(-not $name){$name='UnsupportedAction:'+([int]$a[0])};[pscustomobject][ordered]@{Type=$name;DelayMilliseconds=[long][uint32]$a[1]}})
    $triggers=@(foreach($t in $Actual.Triggers){$data=@(foreach($d in $t[3]){[pscustomobject][ordered]@{Type=[uint32]$d[0];DataBase64=[string]$d[1]}});$triggerAction='UnsupportedAction:'+([uint32]$t[1]);if([uint32]$t[1] -eq 1){$triggerAction='Start'}elseif([uint32]$t[1] -eq 2){$triggerAction='Stop'};[pscustomobject][ordered]@{Type=[uint32]$t[0];Action=$triggerAction;Subtype=[string]$t[2];DataItems=$data}})
    [pscustomobject][ordered]@{ServiceType=$type;ErrorControl=$error;LoadOrderGroup=[string]$Actual.LoadOrderGroup;DelayedAutoStart=[bool]$Actual.DelayedAutoStart;FailureActions=[pscustomobject][ordered]@{ResetPeriodSeconds=$reset;RebootMessage=[string]$f[1];Command=[string]$f[2];Actions=$actions};FailureActionsOnNonCrashFailures=[bool]$Actual.FailureActionsOnNonCrashFailures;ServiceSidType=$sid;RequiredPrivileges=@($Actual.RequiredPrivileges);Environment=@($Actual.Environment);Triggers=$triggers}
}
function Get-WsmServiceSupplementState([string]$Name) {
    Assert-WsmServiceSupplementName $Name;$native=Get-WsmServiceSupplementNativeState $Name;$typed=[pscustomobject][ordered]@{ServiceType=$native[0];ErrorControl=$native[1];LoadOrderGroup=$native[2];DelayedAutoStart=$native[3];FailureActions=$native[4];FailureActionsOnNonCrashFailures=$native[5];ServiceSidType=$native[6];RequiredPrivileges=$native[7];Environment=@(Get-WsmServiceEnvironment $Name);Triggers=$native[8]};ConvertFrom-WsmServiceSupplementState $typed
}
function Get-WsmServiceSupplementForPhase($Supplement,[ValidateSet('Staged','Final')][string]$Phase) {
    if($Phase -eq 'Final'){return $Supplement}
    $actions=@(foreach($nullAction in $Supplement.FailureActions.Actions){[pscustomobject][ordered]@{Type='None';DelayMilliseconds=[long]0}})
    $failure=[pscustomobject][ordered]@{ResetPeriodSeconds=$Supplement.FailureActions.ResetPeriodSeconds;RebootMessage='';Command='';Actions=$actions}
    [pscustomobject][ordered]@{ServiceType=$Supplement.ServiceType;ErrorControl=$Supplement.ErrorControl;LoadOrderGroup=$Supplement.LoadOrderGroup;DelayedAutoStart=$Supplement.DelayedAutoStart;FailureActions=$failure;FailureActionsOnNonCrashFailures=$false;ServiceSidType=$Supplement.ServiceSidType;RequiredPrivileges=@($Supplement.RequiredPrivileges);Environment=@($Supplement.Environment);Triggers=@()}
}
function Set-WsmServiceSupplement([string]$Name,$Supplement,[ValidateSet('Staged','Final')][string]$Phase='Staged') {
    Assert-WsmServiceSupplementName $Name;$null=Assert-WsmServiceSupplement $Supplement;$phaseSupplement=Get-WsmServiceSupplementForPhase $Supplement $Phase;$null=Assert-WsmServiceSupplement $phaseSupplement;$nativeInput=ConvertTo-WsmServiceSupplementNativeInput $phaseSupplement
    Invoke-WsmServiceSupplementNative $Name $nativeInput;Set-WsmServiceEnvironment $Name $nativeInput.Environment
    $state=Get-WsmServiceSupplementState $Name;$check=Test-WsmServiceSupplement $Supplement $state $Phase;if(-not $check.Passed){throw ('Service supplement '+$Phase+' read-back failed: '+($check.Problems -join '; '))};$check
}
function Test-WsmServiceSupplement($Supplement,$Actual,[ValidateSet('Staged','Final')][string]$Phase='Final') {
    $issues=New-Object 'System.Collections.Generic.List[string]';try{$null=Assert-WsmServiceSupplement $Supplement;$null=Assert-WsmServiceSupplement $Actual}catch{$issues.Add($_.Exception.Message);return [pscustomobject]@{Passed=$false;Problems=$issues.ToArray()}}
    $expected=Get-WsmServiceSupplementForPhase $Supplement $Phase
    foreach($field in @('ServiceType','ErrorControl','LoadOrderGroup','ServiceSidType')){if([string]$Actual.$field -cne [string]$expected.$field){$issues.Add(('Service '+$field+' mismatch'))}};if([bool]$Actual.DelayedAutoStart -ne [bool]$expected.DelayedAutoStart){$issues.Add('Service delayed-auto-start mismatch')};if((@($Actual.RequiredPrivileges | Sort-Object -CaseSensitive) -join "`n") -cne (@($expected.RequiredPrivileges | Sort-Object -CaseSensitive) -join "`n")){$issues.Add('Service required-privilege list mismatch')};if((@($Actual.Environment | Sort-Object -CaseSensitive) -join "`n") -cne (@($expected.Environment | Sort-Object -CaseSensitive) -join "`n")){$issues.Add('Service environment mismatch')}
    $observed=$Actual.FailureActions;if([string]$observed.ResetPeriodSeconds -cne [string]$expected.FailureActions.ResetPeriodSeconds -or [string]$observed.RebootMessage -cne [string]$expected.FailureActions.RebootMessage -or [string]$observed.Command -cne [string]$expected.FailureActions.Command){$issues.Add('Service failure-action reset/message/command mismatch')};if([bool]$Actual.FailureActionsOnNonCrashFailures -ne [bool]$expected.FailureActionsOnNonCrashFailures){$issues.Add('Service failure-actions flag mismatch')};$expectedActions=@($expected.FailureActions.Actions);$actualActions=@($observed.Actions);if($expectedActions.Count -ne $actualActions.Count){$issues.Add('Service failure-action count mismatch')}else{for($n=0;$n -lt $expectedActions.Count;$n++){if($expectedActions[$n].Type -cne $actualActions[$n].Type -or [long]$expectedActions[$n].DelayMilliseconds -ne [long]$actualActions[$n].DelayMilliseconds){$issues.Add(('Service failure action mismatch at '+$n));break}}}
    $expectedTriggers=@($expected.Triggers);$actualTriggers=@($Actual.Triggers);if($expectedTriggers.Count -ne $actualTriggers.Count){$issues.Add('Service trigger count mismatch')}else{for($t=0;$t -lt $expectedTriggers.Count;$t++){$et=$expectedTriggers[$t];$at=$actualTriggers[$t];$subtypeMatches=([string]$et.Subtype -ceq [string]$at.Subtype);if($et.Subtype -and $at.Subtype){$eg=[Guid]::Empty;$ag=[Guid]::Empty;if([Guid]::TryParse($et.Subtype,[ref]$eg) -and [Guid]::TryParse($at.Subtype,[ref]$ag)){$subtypeMatches=($eg -eq $ag)}};$triggerMatches=([uint32]$et.Type -eq [uint32]$at.Type -and $et.Action -ceq $at.Action -and $subtypeMatches);$ed=@($et.DataItems);$ad=@($at.DataItems);if($ed.Count -ne $ad.Count){$triggerMatches=$false}else{for($d=0;$d -lt $ed.Count;$d++){if([uint32]$ed[$d].Type -ne [uint32]$ad[$d].Type -or [string]$ed[$d].DataBase64 -cne [string]$ad[$d].DataBase64){$triggerMatches=$false;break}}};if(-not $triggerMatches){$issues.Add(('Service trigger mismatch at '+$t));break}}}
    [pscustomobject]@{Passed=($issues.Count -eq 0);Problems=$issues.ToArray()}
}
